      this.pursuitShortcutEdgeCount = 0;
      this.trespassDwell = 0;
      this.trespassCheckRemaining = 0;
      this.qaPursuitGiveUpOverride = null;
      this.qaLastPursuitRun = null;
      this.talkHitbox = null;
