  function addWorkroomKeypadHardware() {
    const root = new THREE.Group();
    root.name = "workroom-pin-pad-lock";
    root.position.set(-1.3, FLOOR.BASEMENT, -4.72);
    scene.add(root);
    const plate = roundedBox({ name: "workroom-keypad-backplate", w: 0.46, h: 0.76, d: 0.12, radius: 0.045, y: 1.38, material: M.iron, parent: root, cast: true });
    const displayMaterial = new THREE.MeshBasicMaterial({ color: 0x163128, toneMapped: false });
    const display = roundedBox({ name: "workroom-keypad-display", w: 0.33, h: 0.13, d: 0.025, radius: 0.018, y: 1.62, z: 0.075, material: displayMaterial, parent: root, cast: false });
    const keyMaterial = new THREE.MeshStandardMaterial({ color: 0x282b2c, metalness: 0.55, roughness: 0.46 });
    const keyAccentMaterial = new THREE.MeshStandardMaterial({ color: 0x6b4d28, metalness: 0.62, roughness: 0.4 });
    for (let row = 0; row < 4; row += 1) {
      for (let column = 0; column < 3; column += 1) {
        roundedBox({
          name: `workroom-keypad-physical-key-${row}-${column}`,
          w: 0.075, h: 0.065, d: 0.028, radius: 0.012,
          x: (column - 1) * 0.108,
          y: 1.46 - row * 0.09,
          z: 0.078,
          material: row === 3 && column !== 1 ? keyAccentMaterial : keyMaterial,
          parent: root,
          cast: false,
        });
      }
    }
    const indicatorMaterial = new THREE.MeshStandardMaterial({ color: 0xe6a948, emissive: 0xe6a948, emissiveIntensity: 0.9, roughness: 0.34 });
    const indicator = sphere({ name: "workroom-keypad-access-indicator", radius: 0.035, x: 0.17, y: 1.64, z: 0.095, material: indicatorMaterial, parent: root, cast: false });
    const interaction = {
      type: "workroom-keypad",
      id: "workroom-keypad",
      getLabel: () => state.workroom.unlocked ? "Workroom keypad — access granted" : "Enter Workroom access PIN",
      activate: openWorkroomKeypad,
    };
    addInteractionTarget(plate, interaction);
    addInteractionTarget(display, interaction);
    addInteractionTarget(indicator, interaction);
    workroomScene.keypadRoot = root;
    workroomScene.keypadIndicator = indicator;
    workroomScene.keypadIndicatorMaterial = indicatorMaterial;
    updateWorkroomKeypadPresentation();
  }

  function addWorkroomSecurityHub() {
    const root = new THREE.Group();
    root.name = "workroom-live-monitor-wall";
    root.position.set(0, FLOOR.BASEMENT, -11.54);
    scene.add(root);
    const placeholderMaterial = new THREE.MeshBasicMaterial({ color: 0x07171d, toneMapped: false });
    const bezelMaterial = new THREE.MeshStandardMaterial({ color: 0x171a1d, metalness: 0.72, roughness: 0.34 });
    const indicatorMaterial = new THREE.MeshBasicMaterial({ color: 0x42ff78, toneMapped: false });
    const screenWidth = 1.42;
    const screenHeight = 0.8;
    const columnGap = 0.16;
    const rowGap = 0.18;
    const startX = -0.25;
    for (let index = 0; index < WORKROOM_SECURITY.monitorCount; index += 1) {
      const column = index % WORKROOM_SECURITY.monitorColumns;
      const row = Math.floor(index / WORKROOM_SECURITY.monitorColumns);
      const x = startX + column * (screenWidth + columnGap);
      const y = 1.05 + (WORKROOM_SECURITY.monitorRows - 1 - row) * (screenHeight + rowGap);
      roundedBox({ name: `workroom-monitor-${index + 1}-bezel`, w: screenWidth + 0.13, h: screenHeight + 0.14, d: 0.11, radius: 0.045, x, y, material: bezelMaterial, parent: root, cast: false });
      const screen = new THREE.Mesh(new THREE.PlaneGeometry(screenWidth, screenHeight), placeholderMaterial);
      screen.name = `workroom-live-camera-screen-${index + 1}`;
      // Rounded-box bevels extend beyond their nominal depth. Seat the live
      // image clearly in front of that bevel so the bezel cannot occlude or
      // z-fight with the render-target plane at normal viewing distance.
      screen.position.set(x, y, 0.135);
      screen.castShadow = false;
      screen.receiveShadow = false;
      screen.userData.securitySightTransparent = true;
      root.add(screen);
      const status = sphere({ name: `workroom-monitor-${index + 1}-status`, radius: 0.025, x: x + screenWidth * 0.43, y: y - screenHeight * 0.43, z: 0.165, material: indicatorMaterial, parent: root, cast: false });
      workroomScene.monitorScreens.push(screen);
      workroomScene.monitorStatusLights.push(status);
    }
    roundedBox({ name: "workroom-monitor-network-header", w: 6.35, h: 0.16, d: 0.09, radius: 0.03, x: 2.12, y: 2.65, z: 0, material: M.iron, parent: root, cast: false });
    for (let index = 0; index < 18; index += 1) {
      box({ name: "workroom-monitor-patch-bay-port", w: 0.11, h: 0.035, d: 0.025, x: -0.75 + index * 0.34, y: 0.48, z: 0.08, material: index % 5 === 0 ? M.brass : M.copper, parent: root, cast: false });
    }
    workroomScene.monitorRoot = root;

    // A broad operator console anchors the live wall without closing the
    // central aisle from the keypad door to the relay panel.
    addTable(2.55, -9.25, 4.65, 0.92, FLOOR.BASEMENT, 0, M.blackWood);
    workroomScene.ambience.operatorStations += 1;
    for (const x of [1.05, 2.55, 4.05]) {
      roundedBox({ name: "workroom-operator-keyboard", w: 0.72, h: 0.055, d: 0.26, radius: 0.035, x, y: FLOOR.BASEMENT + 0.83, z: -9.1, rotationX: -0.08, material: M.iron, cast: false });
      const chair = new THREE.Group();
      chair.name = "workroom-rolling-operator-chair";
      chair.position.set(x, FLOOR.BASEMENT, -8.05);
      scene.add(chair);
      cylinder({ name: "workroom-chair-post", radius: 0.055, height: 0.48, segments: 10, y: 0.3, material: M.iron, parent: chair });
      roundedBox({ name: "workroom-chair-seat", w: 0.58, h: 0.12, d: 0.54, radius: 0.08, y: 0.58, material: M.leather, parent: chair });
      roundedBox({ name: "workroom-chair-back", w: 0.58, h: 0.72, d: 0.12, radius: 0.08, y: 1.02, z: 0.22, rotationX: -0.12, material: M.leather, parent: chair });
      for (const angle of [0, Math.PI * 0.4, Math.PI * 0.8, Math.PI * 1.2, Math.PI * 1.6]) {
        const wheelX = Math.sin(angle) * 0.28;
        const wheelZ = Math.cos(angle) * 0.28;
        cylinder({ name: "workroom-chair-wheel", radius: 0.045, height: 0.08, segments: 8, x: wheelX, y: 0.07, z: wheelZ, rotationZ: Math.PI / 2, material: M.iron, parent: chair, cast: false });
      }
      workroomScene.ambience.chairs += 1;
    }

    for (const [index, z] of [-10.35, -8.55, -6.75].entries()) {
      const rack = roundedBox({ name: `workroom-server-rack-${index + 1}`, w: 0.72, h: 2.35, d: 1.2, radius: 0.055, x: 7.08, y: FLOOR.BASEMENT + 1.18, z, material: M.iron, cast: true });
      rack.rotation.y = Math.PI / 2;
      physics.addFixedBox(7.08, FLOOR.BASEMENT + 1.18, z, 0.72, 2.35, 1.2, Math.PI / 2);
      for (let slot = 0; slot < 8; slot += 1) {
        box({ name: "workroom-server-blade", w: 0.035, h: 0.16, d: 0.82, x: 6.66, y: FLOOR.BASEMENT + 0.27 + slot * 0.25, z, material: slot % 3 === 0 ? M.copper : M.blackWood, cast: false });
      }
      workroomScene.ambience.serverRacks += 1;
    }

    for (const z of [-10.8, -8.9, -7.0, -5.45]) {
      box({ name: "workroom-overhead-cable-tray", w: 0.16, h: 0.12, d: 1.25, x: 6.75, y: FLOOR.BASEMENT + 3.08, z, material: M.iron, cast: false });
      for (const offset of [-0.045, 0, 0.045]) cylinder({ name: "workroom-data-cable-bundle", radius: 0.018, height: 1.16, segments: 7, x: 6.75 + offset, y: FLOOR.BASEMENT + 3.04, z, rotationX: Math.PI / 2, material: offset === 0 ? M.copper : M.soot, cast: false });
      workroomScene.ambience.cableTrays += 1;
    }

    for (const [index, x] of [-4.8, -3.95].entries()) {
      roundedBox({ name: `workroom-equipment-case-${index + 1}`, w: 0.72, h: 0.48, d: 0.62, radius: 0.055, x, y: FLOOR.BASEMENT + 0.24, z: -10.95, material: M.iron, cast: true });
      box({ name: "workroom-equipment-case-latch", w: 0.12, h: 0.08, d: 0.03, x, y: FLOOR.BASEMENT + 0.34, z: -10.62, material: M.brass, cast: false });
      workroomScene.ambience.equipmentCases += 1;
    }

    // Small human traces keep the room from reading like a sterile prop set.
    roundedBox({ name: "workroom-two-way-radio", w: 0.2, h: 0.34, d: 0.11, radius: 0.025, x: 4.6, y: FLOOR.BASEMENT + 0.98, z: -9.2, material: M.iron, cast: false });
    cylinder({ name: "workroom-radio-antenna", radius: 0.012, height: 0.28, segments: 7, x: 4.66, y: FLOOR.BASEMENT + 1.27, z: -9.2, material: M.soot, cast: false });
    cylinder({ name: "workroom-abandoned-coffee-cup", radius: 0.07, radiusTop: 0.065, radiusBottom: 0.055, height: 0.16, segments: 12, x: 0.35, y: FLOOR.BASEMENT + 0.9, z: -9.05, material: M.porcelain, cast: false });
    // Keep the shift-log stack fully on the 4.65×0.92 operator console
    // (center 2.55,-9.25). Earlier x≈0.1 placements hung off the west edge.
    for (let index = 0; index < 5; index += 1) {
      box({
        name: "workroom-shift-log-paper",
        w: 0.34,
        h: 0.012,
        d: 0.24,
        x: 1.18 + index * 0.028,
        y: FLOOR.BASEMENT + 0.9 + index * 0.004,
        z: -9.32 + index * 0.012,
        rotationY: -0.1 + index * 0.045,
        material: M.canvasLinen,
        cast: false,
      });
    }
    for (let index = 0; index < 4; index += 1) roundedBox({ name: "workroom-archive-binder", w: 0.1, h: 0.42, d: 0.3, radius: 0.015, x: -5.55, y: FLOOR.BASEMENT + 0.31, z: -6.15 - index * 0.34, rotationY: Math.PI / 2, material: index % 2 ? M.leather : M.darkWood, cast: false });
    workroomScene.ambience.smallProps += 12;
  }

  function furnishBasement() {
    for (const z of [5.0, 7.8, 10.5]) addWineRack(-14.35, z, FLOOR.BASEMENT, -Math.PI / 2, 2.25);
    for (const x of [-11.5, -8.8, -6.1, -3.4]) addWineRack(x, 11.55, FLOOR.BASEMENT, 0, 2.35);
    addTable(-8.0, 7.4, 2.6, 1.05, FLOOR.BASEMENT, 0, M.darkWood);
    new Cabinet({ name: "wine cabinet", x: -2.0, z: 9.6, floorY: FLOOR.BASEMENT, width: 1.55, height: 1.9, rotationY: -Math.PI / 2, stockKind: "cellar-reserve", interiorLight: false });
    addWineCellarDetails();

    // Archive — the perimeter is intentionally bare. Three double-sided rows
    // stand well clear of every wall and split at the doorway datum, leaving
    // a continuous cross-aisle plus access around every shelf face and end.
    const archiveRowXs = [3.4, 7.3, 11.2];
    const archiveShelfBanks = [
      { id: "south", z: 5.25, width: 2.1 },
      { id: "north", z: 9.4, width: 2.6 },
    ];
    const archiveCurios = new Map([
      ["1-north", "sealed-ledger"],
      ["2-north", "skull"],
      ["3-south", "reel-to-reel"],
      ["3-north", "specimen-jar"],
    ]);
    archiveRowXs.forEach((x, rowIndex) => archiveShelfBanks.forEach((bank, bankIndex) => {
      const rowNumber = rowIndex + 1;
      addArchiveShelfBank({
        name: `archive-row-${rowNumber}-${bank.id}`,
        x,
        z: bank.z,
        floorY: FLOOR.BASEMENT,
        rotationY: Math.PI / 2,
        width: bank.width,
        height: 3.05,
        depth: 0.72,
        seed: rowIndex * 2 + bankIndex,
        curio: archiveCurios.get(`${rowNumber}-${bank.id}`) || null,
      });
    }));

    // Laundry & linen
    new Cabinet({ name: "linen cupboard", x: -14.2, z: 0.2, floorY: FLOOR.BASEMENT, width: 1.75, height: 2.15, rotationY: Math.PI / 2, stockKind: "linens", interiorLight: false });
    addTable(-8.0, -0.1, 2.6, 1.15, FLOOR.BASEMENT, 0, M.darkWood);
    addLaundryDetails();

    // Pantry storage — five semantic cupboards line the solid walls while the
    // doorway, archive opening, service-stair approach, and broad center aisle
    // stay clear. Pantry stock uses the room ceiling fixture instead of adding
    // five door-operated spots to the estate's fixed shader-light budget.
    new Cabinet({ name: "pantry cupboard", x: 2.1, z: 1.8, floorY: FLOOR.BASEMENT, width: 1.7, height: 2.25, rotationY: Math.PI / 2, stockKind: "pantry-staples", interiorLight: false });
    new Cabinet({ name: "preserves cabinet", x: 6.2, z: 2.65, floorY: FLOOR.BASEMENT, width: 1.8, height: 2.15, rotationY: Math.PI, material: M.darkWood, stockKind: "preserves", interiorLight: false });
    for (const pantryCabinet of [
      { name: "pantry dry-goods cabinet", x: 4.0, stockKind: "dry-goods" },
      { name: "pantry baking cabinet", x: 6.15, stockKind: "baking" },
      { name: "pantry tinned-goods cabinet", x: 8.3, stockKind: "tinned-goods" },
    ]) {
      new Cabinet({
        ...pantryCabinet,
        z: -2.72,
        floorY: FLOOR.BASEMENT,
        width: 1.8,
        height: 2.25,
        depth: 0.56,
        rotationY: 0,
        openAngle: 88,
        material: M.darkWood,
        interiorLight: false,
      });
    }

    addBoiler(-10.2, -8.6, FLOOR.BASEMENT);
    addBoiler(-7.8, -8.8, FLOOR.BASEMENT);
    addPipeRun([[-10.2, -1.35, -8.6], [-10.2, -0.65, -8.6], [-10.2, -0.65, -5.2], [-2.2, -0.65, -5.2]], 0.075, M.copper);
    addPipeRun([[-7.8, -1.3, -8.8], [-7.8, -0.9, -10.7], [4.4, -0.9, -10.7]], 0.065, M.iron);
    addTable(-2.5, -8.2, 3.1, 1.25, FLOOR.BASEMENT, 0, M.darkWood);
    new Cabinet({ name: "workroom tool cabinet", x: -5.3, z: -8.4, floorY: FLOOR.BASEMENT, width: 1.6, height: 1.75, rotationY: Math.PI / 2, stockKind: "tools", interiorLight: false });
    addWorkroomKeypadHardware();
    addWorkroomSecurityHub();
    addBoilerRoomDetails();
    addRearCorridorServicePipes();
    addBulkStorageDetails();
  }

  function createContestantThirteenScratchTexture() {
    const canvas = document.createElement("canvas");
    canvas.width = 256;
    canvas.height = 192;
    const ctx = canvas.getContext("2d");
    const scratchPaths = [
      [[32, 24], [41, 47], [48, 70], [60, 96], [73, 126], [88, 164]],
      [[88, 27], [79, 48], [70, 73], [59, 98], [45, 128], [31, 162]],
      [[112, 31], [108, 56], [113, 82], [108, 108], [114, 133], [110, 162]],
      [[157, 28], [153, 52], [158, 78], [152, 105], [159, 132], [155, 164]],
      [[204, 31], [199, 56], [205, 80], [198, 108], [204, 136], [200, 161]],
    ];
    const crossIntersection = [
      [[52, 78], [60, 96], [69, 116]],
      [[69, 79], [59, 98], [49, 117]],
    ];
    const trace = (path) => {
      ctx.beginPath();
      ctx.moveTo(path[0][0], path[0][1]);
      for (let index = 1; index < path.length; index += 1) ctx.lineTo(path[index][0], path[index][1]);
      ctx.stroke();
    };
    ctx.lineCap = "round";
    ctx.lineJoin = "round";
    ctx.strokeStyle = "rgba(14, 10, 7, 0.68)";
    ctx.lineWidth = 5.2;
    ctx.setLineDash([16, 2, 11, 5]);
    scratchPaths.forEach(trace);
    ctx.strokeStyle = "rgba(190, 170, 126, 0.72)";
    ctx.lineWidth = 1.7;
    ctx.setLineDash([13, 4, 8, 3]);
    ctx.lineDashOffset = 2;
    scratchPaths.forEach(trace);
    ctx.strokeStyle = "rgba(218, 199, 151, 0.34)";
    ctx.lineWidth = 0.7;
    ctx.setLineDash([5, 8, 3, 11]);
    ctx.lineDashOffset = -3;
    scratchPaths.forEach((path, index) => trace(path.map(([x, y], pointIndex) => [x + ((index + pointIndex) % 2 ? 1.4 : -0.8), y + 0.9])));
    ctx.setLineDash([]);
    ctx.strokeStyle = "rgba(14, 10, 7, 0.76)";
    ctx.lineWidth = 3.8;
    crossIntersection.forEach(trace);
    ctx.strokeStyle = "rgba(205, 184, 137, 0.78)";
    ctx.lineWidth = 1.25;
    crossIntersection.forEach(trace);
    const texture = new THREE.CanvasTexture(canvas);
    texture.name = "contestant-13-library-book-etched-xiii";
    texture.wrapS = texture.wrapT = THREE.ClampToEdgeWrapping;
    texture.magFilter = THREE.LinearFilter;
    texture.minFilter = THREE.LinearFilter;
    texture.generateMipmaps = false;
    texture.encoding = THREE.sRGBEncoding;
    return texture;
  }

  const WORKROOM_SCRATCH_GLYPHS = Object.freeze({
    I: Object.freeze([
      [[0.18, 0.08], [0.82, 0.06]],
      [[0.51, 0.06], [0.47, 0.3], [0.53, 0.57], [0.48, 0.93]],
      [[0.17, 0.94], [0.8, 0.92]],
    ]),
    V: Object.freeze([
      [[0.1, 0.07], [0.21, 0.35], [0.49, 0.94], [0.77, 0.39], [0.91, 0.06]],
    ]),
    "0": Object.freeze([
      [[0.35, 0.06], [0.18, 0.15], [0.1, 0.39], [0.13, 0.73], [0.3, 0.93], [0.66, 0.92], [0.84, 0.74], [0.9, 0.4], [0.77, 0.14], [0.35, 0.06]],
    ]),
    "1": Object.freeze([
      [[0.22, 0.24], [0.5, 0.06], [0.48, 0.94]],
      [[0.19, 0.94], [0.79, 0.92]],
    ]),
    "3": Object.freeze([
      [[0.16, 0.13], [0.42, 0.05], [0.71, 0.1], [0.86, 0.26], [0.74, 0.44], [0.47, 0.5], [0.74, 0.55], [0.88, 0.72], [0.76, 0.9], [0.47, 0.96], [0.15, 0.88]],
    ]),
    "5": Object.freeze([
      [[0.86, 0.08], [0.22, 0.06], [0.17, 0.48], [0.65, 0.47], [0.84, 0.58], [0.81, 0.81], [0.64, 0.94], [0.22, 0.91]],
    ]),
  });

  function createWorkroomScratchTexture(numeral, digit) {
    const canvas = document.createElement("canvas");
    canvas.width = WORKROOM_CODE_SCRATCH_STYLE.textureWidth;
    canvas.height = WORKROOM_CODE_SCRATCH_STYLE.textureHeight;
    const ctx = canvas.getContext("2d");
    let seed = 2166136261;
    for (const character of `${numeral}:${digit}`) seed = Math.imul(seed ^ character.charCodeAt(0), 16777619) >>> 0;
    const random = () => {
      seed = (seed + 0x6d2b79f5) >>> 0;
      let value = seed;
      value = Math.imul(value ^ (value >>> 15), value | 1);
      value ^= value + Math.imul(value ^ (value >>> 7), value | 61);
      return ((value ^ (value >>> 14)) >>> 0) / 4294967296;
    };
    const roughenPath = (source) => {
      const rough = [];
      for (let segmentIndex = 1; segmentIndex < source.length; segmentIndex += 1) {
        const from = source[segmentIndex - 1];
        const to = source[segmentIndex];
        const dx = to[0] - from[0];
        const dy = to[1] - from[1];
        const length = Math.max(0.001, Math.hypot(dx, dy));
        const steps = Math.max(2, Math.ceil(length / 13));
        for (let step = 0; step < steps; step += 1) {
          if (segmentIndex > 1 && step === 0) continue;
          const progress = step / steps;
          const endDamping = progress < 0.001 ? 0.35 : 1;
          const lateral = (random() - 0.5) * 3.4 * endDamping;
          const along = (random() - 0.5) * 1.2 * endDamping;
          rough.push([
            from[0] + dx * progress + (dx / length) * along - (dy / length) * lateral,
            from[1] + dy * progress + (dy / length) * along + (dx / length) * lateral,
          ]);
        }
      }
      const last = source[source.length - 1];
      rough.push([last[0] + (random() - 0.5) * 0.8, last[1] + (random() - 0.5) * 0.8]);
      return rough;
    };
    const glyphWidth = 50;
    const glyphHeight = 112;
    const glyphGap = 10;
    const separatorWidth = 44;
    const numeralWidth = numeral.length * glyphWidth + Math.max(0, numeral.length - 1) * glyphGap;
    const contentWidth = numeralWidth + separatorWidth + glyphWidth;
    const glyphTop = 23;
    let cursorX = (canvas.width - contentWidth) / 2;
    const scratchPaths = [];
    const appendGlyph = (character, originX) => {
      for (const sourcePath of WORKROOM_SCRATCH_GLYPHS[character] || []) {
        scratchPaths.push(roughenPath(sourcePath.map(([x, y]) => [originX + x * glyphWidth, glyphTop + y * glyphHeight])));
      }
    };
    for (const character of numeral) {
      appendGlyph(character, cursorX);
      cursorX += glyphWidth + glyphGap;
    }
    cursorX -= glyphGap;
    scratchPaths.push(roughenPath([
      [cursorX + 9, glyphTop + glyphHeight * 0.52],
      [cursorX + separatorWidth - 9, glyphTop + glyphHeight * 0.49],
    ]));
    cursorX += separatorWidth;
    appendGlyph(digit, cursorX);

    const trace = (path, offsetX = 0, offsetY = 0) => {
      ctx.beginPath();
      ctx.moveTo(path[0][0] + offsetX, path[0][1] + offsetY);
      for (let index = 1; index < path.length; index += 1) ctx.lineTo(path[index][0] + offsetX, path[index][1] + offsetY);
      ctx.stroke();
    };
    const fibers = Array.from({ length: 16 }, (_, index) => {
      const sourcePath = scratchPaths[index % scratchPaths.length];
      const point = sourcePath[Math.floor(random() * sourcePath.length)];
      const angle = (random() - 0.5) * 2.2;
      const length = 5 + random() * 9;
      return roughenPath([
        [point[0] - Math.cos(angle) * length * 0.5, point[1] - Math.sin(angle) * length * 0.5],
        [point[0] + Math.cos(angle) * length * 0.5, point[1] + Math.sin(angle) * length * 0.5],
      ]);
    });

    ctx.save();
    ctx.translate(canvas.width / 2, canvas.height / 2);
    ctx.rotate(-0.035);
    ctx.translate(-canvas.width / 2, -canvas.height / 2);
    ctx.lineCap = "round";
    ctx.lineJoin = "round";
    // Match the book-spine XIII: an irregular dark undercut, a broken pale
    // plaster core, a hairline highlight, and stray fibers. The glyphs above
    // are traced paths rather than typography, so the marks read as hurried
    // cuts while their numeral/digit shapes remain unambiguous.
    ctx.strokeStyle = "rgba(24, 16, 12, 0.76)";
    ctx.lineWidth = 9.2;
    ctx.setLineDash([17, 3, 10, 5]);
    scratchPaths.forEach((path) => trace(path, 1.5, 1.7));
    ctx.strokeStyle = "rgba(214, 196, 158, 0.94)";
    ctx.lineWidth = 4.6;
    ctx.setLineDash([14, 3, 8, 4]);
    ctx.lineDashOffset = 1;
    scratchPaths.forEach((path) => trace(path));
    ctx.strokeStyle = "rgba(240, 226, 194, 0.62)";
    ctx.lineWidth = 1.25;
    ctx.setLineDash([5, 8, 3, 10]);
    ctx.lineDashOffset = -3;
    scratchPaths.forEach((path) => trace(path, -0.7, -0.8));
    ctx.strokeStyle = "rgba(35, 23, 16, 0.64)";
    ctx.lineWidth = 1.6;
    ctx.setLineDash([5, 3, 2, 4]);
    fibers.forEach((path) => trace(path, 0.8, 0.9));
    ctx.strokeStyle = "rgba(222, 204, 166, 0.72)";
    ctx.lineWidth = 0.65;
    ctx.setLineDash([3, 4, 2, 5]);
    fibers.forEach((path) => trace(path));
    ctx.restore();
    const texture = new THREE.CanvasTexture(canvas);
    texture.name = `workroom-code-scratch-${numeral}`;
    texture.wrapS = texture.wrapT = THREE.ClampToEdgeWrapping;
    texture.magFilter = THREE.LinearFilter;
    texture.minFilter = THREE.LinearFilter;
    texture.generateMipmaps = false;
    texture.encoding = THREE.sRGBEncoding;
    return texture;
  }

  function addWorkroomCodeScratch(options) {
    const config = WORKROOM_CODE_SCRATCHES.find((candidate) => candidate.artId === options.artId);
    if (!config || !workroomCodeClue) return;
    const { axis, fixed, center, centerY = 1.95, side = 1, width = 1, height = 1.4 } = options;
    const carrierEntry = tamperSystem?.entries.find((entry) => entry.kind === "portrait" && entry.artId === config.artId);
    const tiltSign = carrierEntry?.tiltSign || 1;
    const tiltRadians = carrierEntry?.tiltRadians || WORKROOM_CODE_SCRATCH_STYLE.carrierTiltRadians;
    // The scratch sits just proud of the wall surface (walls are 0.28m boxes
    // centered on `fixed`, so the face is 0.14m out), well behind the
    // painting's 0.19m stand-off, anchored to a sibling group so tilting the
    // painting never moves the mark it conceals.
    const wallGap = 0.152;
    let x;
    let z;
    let rotationY;
    if (axis === "x") {
      x = center;
      z = fixed + side * wallGap;
      rotationY = side > 0 ? 0 : Math.PI;
    } else {
      x = fixed + side * wallGap;
      z = center;
      rotationY = side > 0 ? Math.PI / 2 : -Math.PI / 2;
    }
    const anchor = new THREE.Group();
    anchor.name = `workroom-code-scratch-${config.artId}`;
    // Each painting alternates its roll direction. Put the mark under the
    // bottom corner that rises for this carrier instead of always using the
    // left side (which left two of the four clues under the lowered rail).
    const localX = tiltSign * Math.max(
      WORKROOM_CODE_SCRATCH_STYLE.planeWidth / 2,
      width / 2 - WORKROOM_CODE_SCRATCH_STYLE.planeWidth / 2 + WORKROOM_CODE_SCRATCH_STYLE.cornerBias,
    );
    const localY = -height / 2 - WORKROOM_CODE_SCRATCH_STYLE.bottomOffset;
    anchor.position.set(x, FLOOR.MAIN + centerY + localY, z);
    anchor.rotation.y = rotationY;
    anchor.userData.workroomScratchPlacement = {
      tiltSign,
      tiltRadians,
      revealCorner: tiltSign > 0 ? "bottom-right" : "bottom-left",
      portraitWidth: width,
      portraitHeight: height,
      frameRail: MANSION_PORTRAIT.frameRail,
      localX,
      localY,
      planeWidth: WORKROOM_CODE_SCRATCH_STYLE.planeWidth,
      planeHeight: WORKROOM_CODE_SCRATCH_STYLE.planeHeight,
      surfaceTreatment: "etched-decal",
      raisedDepth: 0,
      textureTechnique: "hand-traced-broken-gouges",
    };
    scene.add(anchor);
    const scratch = new THREE.Mesh(
      new THREE.PlaneGeometry(WORKROOM_CODE_SCRATCH_STYLE.planeWidth, WORKROOM_CODE_SCRATCH_STYLE.planeHeight),
      new THREE.MeshBasicMaterial({
        map: createWorkroomScratchTexture(config.numeral, config.digit),
        transparent: true,
        alphaTest: 0.035,
        depthWrite: false,
        toneMapped: true,
        side: THREE.FrontSide,
      }),
    );
    scratch.name = `workroom-code-scratch-mark-${config.artId}`;
    scratch.position.set(localX, 0, 0);
    scratch.renderOrder = 6;
    scratch.castShadow = false;
    scratch.receiveShadow = false;
    scratch.userData.surfaceTreatment = "etched-decal";
    scratch.userData.raisedDepth = 0;
    anchor.add(scratch);
    workroomCodeClue.registerScratch(config.artId, anchor);
  }

